namespace sv_05af81ed0b80403faac97643ebf86742.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

public class InMemorySettingsService : ISettingsService
{
    private UserProfile _profile = new("Jane Doe", "jane@example.com", "https://via.placeholder.com/100", "Software developer and coffee enthusiast.");
    private NotificationPrefs _notificationPrefs = new(true, false, true, new List<string> { "marketing" });
    private SecuritySettings _security = new(false, DateTime.Now.AddDays(-30), new List<ActiveSession>
    {
        new("s1", "Chrome on Windows", "New York, US", DateTime.Now.AddMinutes(-5)),
        new("s2", "Safari on iPhone", "London, UK", DateTime.Now.AddHours(-2)),
        new("s3", "Firefox on Linux", "Berlin, DE", DateTime.Now.AddDays(-1))
    });
    private AppearanceSettings _appearance = new("Light", "Medium", "English", false);

    public Task<UserProfile> GetProfileAsync() => Task.FromResult(_profile);

    public Task SaveProfileAsync(UserProfile profile)
    {
        _profile = profile;
        return Task.CompletedTask;
    }

    public Task<NotificationPrefs> GetNotificationPrefsAsync() => Task.FromResult(_notificationPrefs);

    public Task SaveNotificationPrefsAsync(NotificationPrefs prefs)
    {
        _notificationPrefs = prefs;
        return Task.CompletedTask;
    }

    public Task<SecuritySettings> GetSecuritySettingsAsync() => Task.FromResult(_security);

    public Task ChangePasswordAsync(string currentPassword, string newPassword)
    {
        _security = _security with { LastPasswordChange = DateTime.Now };
        return Task.CompletedTask;
    }

    public Task RevokeSessionAsync(string sessionId)
    {
        _security = _security with
        {
            Sessions = _security.Sessions.Where(s => s.Id != sessionId).ToList()
        };
        return Task.CompletedTask;
    }

    public Task<AppearanceSettings> GetAppearanceAsync() => Task.FromResult(_appearance);

    public Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        _appearance = settings;
        return Task.CompletedTask;
    }
}

@namespace sv_05af81ed0b80403faac97643ebf86742.Components.Pages.Settings

<nav class="settings-sidebar">
    @foreach (var section in Sections)
    {
        <button class="sidebar-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionSelected.InvokeAsync(section)">
            <span class="sidebar-icon">@GetIcon(section)</span>
            <span class="sidebar-label">@section</span>
        </button>
    }
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionSelected { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_05af81ed0b80403faac97643ebf86742.Components.Pages.Settings
@using sv_05af81ed0b80403faac97643ebf86742.Services

<div class="settings-section">
    <h2>Profile</h2>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="avatar-preview">
            <img src="@_avatarUrl" alt="Avatar" class="avatar-image" />
            <span class="avatar-url">@_avatarUrl</span>
        </div>

        <div class="form-group">
            <label for="displayName">Display Name</label>
            <input id="displayName" type="text" @bind="_displayName" class="form-control" />
        </div>

        <div class="form-group">
            <label for="email">Email</label>
            <input id="email" type="email" @bind="_email" class="form-control" />
        </div>

        <div class="form-group">
            <label for="bio">Bio</label>
            <textarea id="bio" @bind="_bio" class="form-control" rows="4"></textarea>
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SaveChanges">Save Changes</button>
            <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="toast-message success">@_message</div>
        }
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private string _message = "";
    private bool _loading = true;

    private UserProfile? _savedProfile;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        _loading = true;
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(updated);
        _savedProfile = updated;
        _message = "Profile saved successfully!";
        _ = ClearMessageAfterDelay();
    }

    private void DiscardChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        _message = "";
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _message = "";
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_05af81ed0b80403faac97643ebf86742.Components.Pages.Settings
@using sv_05af81ed0b80403faac97643ebf86742.Services

<div class="settings-section">
    <h2>Notifications</h2>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <div class="toggle-group">
            <label class="toggle-item">
                <input type="checkbox" @bind="_emailNotifications" />
                <span>Email Notifications</span>
            </label>
            <label class="toggle-item">
                <input type="checkbox" @bind="_pushNotifications" />
                <span>Push Notifications</span>
            </label>
            <label class="toggle-item">
                <input type="checkbox" @bind="_weeklyDigest" />
                <span>Weekly Digest</span>
            </label>
        </div>

        <h3>Muted Channels</h3>
        <div class="channel-list">
            @foreach (var channel in _allChannels)
            {
                <label class="channel-item">
                    <input type="checkbox"
                           checked="@_mutedChannels.Contains(channel)"
                           @onchange="e => ToggleChannel(channel, (bool)e.Value!)" />
                    <span>@channel</span>
                </label>
            }
        </div>

        <div class="form-actions">
            <button class="btn btn-primary" @onclick="SavePreferences">Save Preferences</button>
        </div>

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="toast-message success">@_message</div>
        }
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private HashSet<string> _mutedChannels = new();
    private bool _loading = true;
    private string _message = "";

    private static readonly string[] _allChannels = { "general", "engineering", "marketing", "support", "random" };

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new HashSet<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            _mutedChannels.Add(channel);
        else
            _mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels.ToList());
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _message = "Preferences saved!";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _message = "";
        await InvokeAsync(StateHasChanged);
    }
}

@namespace sv_05af81ed0b80403faac97643ebf86742.Components.Pages.Settings
@using sv_05af81ed0b80403faac97643ebf86742.Services

<div class="settings-section">
    <h2>Security</h2>

    @if (_loading)
    {
        <p>Loading...</p>
    }
    else
    {
        <!-- Change Password Panel -->
        <div class="expandable-panel">
            <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                <span>Change Password</span>
                <span class="expand-icon">@(_passwordPanelOpen ? "▾" : "▸")</span>
            </button>
            @if (_passwordPanelOpen)
            {
                <div class="panel-body">
                    <div class="form-group">
                        <label for="currentPassword">Current Password</label>
                        <input id="currentPassword" type="password" @bind="_currentPassword" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label for="newPassword">New Password</label>
                        <input id="newPassword" type="password" @bind="_newPassword" class="form-control" />
                    </div>
                    <div class="form-group">
                        <label for="confirmPassword">Confirm Password</label>
                        <input id="confirmPassword" type="password" @bind="_confirmPassword" class="form-control" />
                    </div>
                    @if (!string.IsNullOrEmpty(_passwordError))
                    {
                        <div class="toast-message error">@_passwordError</div>
                    }
                    <button class="btn btn-primary" @onclick="UpdatePassword">Update Password</button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="twofa-section">
            <label class="toggle-item">
                <input type="checkbox" checked="@_twoFactorEnabled" disabled />
                <span>Two-Factor Authentication</span>
                <span class="status-indicator @(_twoFactorEnabled ? "enabled" : "disabled")">
                    @(_twoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </label>
            @if (_lastPasswordChange.HasValue)
            {
                <p class="info-text">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }
        </div>

        <!-- Active Sessions -->
        <h3>Active Sessions</h3>
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Action</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in _sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != _currentSessionId)
                            {
                                <button class="btn btn-danger btn-sm" @onclick="() => ConfirmRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="current-badge">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>

        <!-- Revoke Confirmation Dialog -->
        @if (_sessionToRevoke is not null)
        {
            <div class="modal-overlay">
                <div class="modal-dialog">
                    <h4>Revoke Session</h4>
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                    <div class="modal-actions">
                        <button class="btn btn-danger" @onclick="RevokeConfirmed">Revoke</button>
                        <button class="btn btn-secondary" @onclick="() => _sessionToRevoke = null">Cancel</button>
                    </div>
                </div>
            </div>
        }

        @if (!string.IsNullOrEmpty(_message))
        {
            <div class="toast-message success">@_message</div>
        }
    }
</div>

@code {
